# 64t_king_dictionary_pilot.R
#
# PILOT ONLY - not wired into any figure. PJ, 11 Sep: the existing
# career_terms dictionary (64q_backbench_frontbench_split.R) turns out to be
# almost entirely office-reference language ("my department", "as Secretary
# of State") rather than genuine career-orientation - of its 18 terms, 17
# fire mechanically off HOLDING a role, only "my career" reflects orientation
# rather than office. PJ's call: build a new dictionary grounded directly in
# King (1981)'s own language about what career politicians actually DO
# (ambition, self-assertion, restlessness, disputatiousness), read page by
# page (pp.278-285) via pypdfium2 rendering (JSTOR scan, no text layer).
#
# CAVEAT flagged before running: King's own words are an ANALYST'S
# description of career politicians (third person, academic register), not
# necessarily language an MP would use about themselves in a live Commons
# speech. This pilot exists to find out empirically which terms actually
# occur in real speech text at a usable rate, rather than assuming King's
# vocabulary transfers directly.
#
# METHOD: same sampling as 64q (seed 42, n=1500/year, same 5 years spread
# across the corpus) - scores EACH candidate term separately (not summed)
# so we can see per-term hit rates, unlike the production scripts which
# only report the combined ratio.
#
# DATA: sources_raw/blumenau_damiani_commons_speeches_1979_2019/extracted/out
# OUTPUT: console only - diagnostic, to decide which terms survive into a
# real dictionary.

suppressMessages({library(dplyr); library(readr); library(stringr); library(purrr)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
DATA_IN   <- file.path(WKBD_ROOT, "sources_raw/blumenau_damiani_commons_speeches_1979_2019/extracted/out")

# ROUND 1 RESULT (11 Sep): King's own literal vocabulary essentially never
# occurs in real speech (analyst's third-person register, not spoken
# register) - 8 of 10 categories scored ZERO across 2m sampled words; only
# "confident_assert" (driven by "i firmly believe", really a generic
# opinion-intensifier, not career-orientation) and "challenge_exec" (11
# hits) had any signal. PJ's call: keep going, but move from King's exact
# words to natural paraphrases of the same CONSTRUCTS (ambition/self-
# advancement, confident assertion/dispute of a different view, wilful
# defiance/not-lobby-fodder) - i.e. what an MP embodying King's mechanism
# would actually say, not King's own description of them.
#
# ROUND 2 candidates below. Dropped: literal King quotes that scored zero
# in round 1 (my ambition, get ahead, make my mark, my own judgment, my own
# interests, eager for office, not for votes, i will not be told/silenced,
# too proud to/not lobby fodder) - replaced with paraphrase equivalents.
# Kept "hold the government/ministers to account" (challenge_exec) since it
# had real signal in round 1. Dropped "i firmly believe" - too close to the
# already-excluded generic opinion-markers (i think/i believe/in my view/i
# feel) to count as a career-orientation signal specifically.
# ROUND 2 RESULT (11 Sep): 57 total hits across the same 5yr/2m-word sample
# (vs 201 for the OLD 18-term office-reference dictionary run on the same
# sample, for comparison) - real signal (5 of 7 categories non-trivial) but
# still ~3.5x sparser. PJ: "good idea to see if we can pull in more words
# otherwise the series is sparse". Dropped tenure_career (0 hits) and
# conscience_defiance (2 hits, too rare) entirely. ROUND 3 below widens the
# 5 surviving categories with more paraphrases of the SAME constructs, plus
# one new category (personal-conviction/whip-defiance, a sharper cut at
# King's p.280 "too proud and wilful... mere lobby fodder" than round 2's
# now-dropped conscience_defiance attempt).
candidates <- list(
  # p.279/282: ambition for office, "eager... accept with alacrity"
  "determination"     = c("i am determined to", "i am determined that", "i will not rest until",
                           "i am committed to", "i will fight for", "i will continue to fight"),
  # p.281: "the self-image, the desire for positive accomplishment"
  "aspiration_legacy" = c("i want to see", "my hope is that", "history will judge",
                           "history will show", "i came into this house to",
                           "i came into politics to", "make a real difference"),
  # p.285: "confident assertion of fundamentally different points of view"
  "fundamental_dispute" = c("i fundamentally disagree", "i cannot support the government",
                             "i cannot support this bill", "i will vote against",
                             "i cannot vote for", "i cannot agree with the government",
                             "i part company with", "i take a different view from the government"),
  # p.279-280: self-assertiveness, "determined to exercise their own judgment"
  "self_assertion"     = c("i speak for myself", "i will speak my mind", "i make no apology",
                            "i stand by what i have said", "i am not prepared to",
                            "no one will tell me"),
  # p.280: select committees / backbench self-assertion outlets
  "challenge_exec"     = c("hold the government to account", "hold ministers to account",
                            "hold this government to account", "scrutinise the government",
                            "the government must answer"),
  # NEW p.280: "too proud and wilful to be content to serve as mere lobby
  # fodder" - sharper cut than round 2's conscience_defiance (dropped)
  "whip_defiance"      = c("defy the whip", "against the party whip", "vote with my conscience",
                            "break with my party", "against my own government"),
  # ROUND 4, 11 Sep: PJ noted "i want to see" (16 hits, round 3's biggest
  # gainer) sits ambiguously between policy-wish ("i want to see more
  # funding") and genuine personal ambition ("i want to see this through").
  # Rather than institutional "my party X" phrasing (whip_defiance, which
  # scored zero), PJ asked to push further on first-person "I want..."
  # constructions specifically anchored to PERSONAL outcome/role/legacy,
  # not policy outcome - a sharper cut at the same vein that produced the
  # one real hit so far.
  "i_want_personal"    = c("i want to be the", "i want to be known as", "i want to be remembered",
                            "i want my name", "i want to lead", "i want to prove",
                            "i want to show that i", "i want to achieve", "what i want is"),
  # ROUND 5, 11 Sep: PJ confirmed keeping "i want to see" and asked for
  # other words "like this" - clarified the distinction before testing:
  # "i believe"/"i think"/"in my view"/"i feel" are EPISTEMIC (state a
  # belief about the world) and stay excluded, as originally decided -
  # different in kind from "i want to see", which is VOLITIONAL (asserts
  # personal will/desire). This category tests other volitional first-
  # person constructions, the real family "i want to see" belongs to.
  "volitional_want"    = c("i would like to see", "i hope to see", "i wish to see",
                            "i want the government to", "i want this house to",
                            "i would like this house to")
)

years <- c(1979, 1990, 2000, 2010, 2019)
set.seed(42)

results <- list()
phrase_hits <- list()
for (yr in years) {
  f <- file.path(DATA_IN, sprintf("%d.csv", yr))
  if (!file.exists(f)) { message("missing: ", f); next }
  d <- read_csv(f, show_col_types = FALSE, progress = FALSE,
                col_select = c(body)) |>
    filter(!is.na(body), nchar(body) > 300)
  samp <- d |> slice_sample(n = min(1500, nrow(d)))
  n_speeches <- nrow(samp)
  n_words <- sum(str_count(samp$body, "\\S+"))

  row <- tibble(year = yr, n_speeches = n_speeches, n_words = n_words)
  for (cat in names(candidates)) {
    terms <- candidates[[cat]]
    hits <- sum(str_count(tolower(samp$body), paste(terms, collapse = "|")))
    row[[cat]] <- hits
  }
  results[[as.character(yr)]] <- row

  # per-phrase diagnostic, pooled into phrase_hits below
  for (cat in names(candidates)) {
    for (term in candidates[[cat]]) {
      key <- paste(cat, term, sep = " :: ")
      h <- sum(str_count(tolower(samp$body), fixed(term)))
      prev <- if (is.null(phrase_hits[[key]])) 0 else phrase_hits[[key]]
      phrase_hits[[key]] <- prev + h
    }
  }
}

out <- bind_rows(results)
cat("\n=== Raw hit counts per candidate category, by year (n=1500 speeches/year) ===\n")
print(as.data.frame(out))

cat("\n=== Total hits across all 5 sampled years, by category ===\n")
totals <- out |> select(-year, -n_speeches, -n_words) |> colSums()
print(sort(totals, decreasing = TRUE))

cat("\n=== Total words sampled ===\n")
print(sum(out$n_words))

cat("\n=== Per-phrase hit counts (diagnostic - check for generic/false-positive-prone phrases) ===\n")
ph <- sort(unlist(phrase_hits), decreasing = TRUE)
for (nm in names(ph)) cat(sprintf("%4d  %s\n", ph[nm], nm))
